package com.example.deskpet;
import android.app.*; import android.os.*; import android.content.*; import android.graphics.PixelFormat; import android.provider.Settings; import android.view.*; import android.widget.*;
public class PetService extends Service {
 WindowManager wm; WindowManager.LayoutParams lp; FrameLayout pet; Handler h=new Handler(Looper.getMainLooper()); boolean dragging=false; int direction=1; TextView heart; float sx,sy; int ox,oy; boolean moved; int size;
 int dp(int n){return (int)(n*getResources().getDisplayMetrics().density+.5f);}
 int maxX(){android.util.DisplayMetrics m=new android.util.DisplayMetrics();wm.getDefaultDisplay().getMetrics(m);return Math.max(0,m.widthPixels-size);}
 int maxY(){android.util.DisplayMetrics m=new android.util.DisplayMetrics();wm.getDefaultDisplay().getMetrics(m);return Math.max(0,m.heightPixels-size);}
 Runnable walk=new Runnable(){public void run(){if(pet==null)return;if(!dragging){lp.x+=direction*dp(2);if(lp.x>=maxX()){lp.x=maxX();direction=-1;}if(lp.x<=0){lp.x=0;direction=1;}lp.y=Math.max(0,Math.min(maxY(),lp.y));wm.updateViewLayout(pet,lp);}h.postDelayed(this,45);}};
 public IBinder onBind(Intent i){return null;}
 public int onStartCommand(Intent i,int flags,int id){if(i!=null&&"STOP".equals(i.getAction())){stopSelf();return START_NOT_STICKY;} if(pet!=null)return START_NOT_STICKY;
 NotificationManager nm=getSystemService(NotificationManager.class);nm.createNotificationChannel(new NotificationChannel("pet","데스크펫",NotificationManager.IMPORTANCE_LOW));PendingIntent stop=PendingIntent.getService(this,1,new Intent(this,PetService.class).setAction("STOP"),PendingIntent.FLAG_IMMUTABLE);startForeground(1,new Notification.Builder(this,"pet").setSmallIcon(android.R.drawable.ic_menu_view).setContentTitle(getString(R.string.app_name)).setContentText("캐릭터 실행 중").addAction(android.R.drawable.ic_menu_close_clear_cancel,"종료",stop).build());if(!Settings.canDrawOverlays(this)){stopSelf();return START_NOT_STICKY;}
 wm=(WindowManager)getSystemService(WINDOW_SERVICE);size=dp(112);pet=new FrameLayout(this);ImageView img=new ImageView(this);img.setImageResource(R.drawable.pet);img.setScaleType(ImageView.ScaleType.FIT_CENTER);FrameLayout.LayoutParams ip=new FrameLayout.LayoutParams(dp(88),dp(88),Gravity.BOTTOM|Gravity.CENTER_HORIZONTAL);pet.addView(img,ip);heart=new TextView(this);heart.setText("♥");heart.setTextColor(0xffef5279);heart.setTextSize(30);heart.setGravity(Gravity.CENTER);heart.setVisibility(View.INVISIBLE);pet.addView(heart,new FrameLayout.LayoutParams(-1,dp(35),Gravity.TOP));lp=new WindowManager.LayoutParams(size,size,WindowManager.LayoutParams.TYPE_APPLICATION_OVERLAY,WindowManager.LayoutParams.FLAG_NOT_FOCUSABLE,PixelFormat.TRANSLUCENT);lp.gravity=Gravity.TOP|Gravity.LEFT;lp.x=0;lp.y=maxY()/2;
 pet.setOnTouchListener((v,e)->{switch(e.getActionMasked()){case MotionEvent.ACTION_DOWN:dragging=true;moved=false;sx=e.getRawX();sy=e.getRawY();ox=lp.x;oy=lp.y;return true;case MotionEvent.ACTION_MOVE:float dx=e.getRawX()-sx,dy=e.getRawY()-sy;if(Math.abs(dx)+Math.abs(dy)>dp(6))moved=true;if(moved){lp.x=Math.max(0,Math.min(maxX(),ox+(int)dx));lp.y=Math.max(0,Math.min(maxY(),oy+(int)dy));wm.updateViewLayout(pet,lp);}return true;case MotionEvent.ACTION_UP:dragging=false;if(!moved){heart.setVisibility(View.VISIBLE);h.removeCallbacks(hide);h.postDelayed(hide,900);}return true;case MotionEvent.ACTION_CANCEL:dragging=false;return true;}return true;});try{wm.addView(pet,lp);}catch(RuntimeException ex){pet=null;stopSelf();return START_NOT_STICKY;}h.post(walk);return START_NOT_STICKY;}
 Runnable hide=()->{if(heart!=null)heart.setVisibility(View.INVISIBLE);};public void onDestroy(){h.removeCallbacksAndMessages(null);if(pet!=null){wm.removeView(pet);pet=null;}stopForeground(true);super.onDestroy();}
}
